import{_t as e,it as t,n,rt as r}from"./chunks/framework.wyZghjns.js";var i=JSON.parse(`{"title":"Class: PlayerSession","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/prismarine/classes/PlayerSession.md","filePath":"api/@jsprismarine/prismarine/classes/PlayerSession.md"}`),a={name:`api/@jsprismarine/prismarine/classes/PlayerSession.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/prismarine</a> / PlayerSession</p><h1 id="class-playersession" tabindex="-1">Class: PlayerSession <a class="header-anchor" href="#class-playersession" aria-label="Permalink to “Class: PlayerSession”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L124" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:124</a></p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new PlayerSession</strong>(<code>server</code>, <code>connection</code>, <code>player</code>): <code>PlayerSession</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L209" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:209</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="server" tabindex="-1">server <a class="header-anchor" href="#server" aria-label="Permalink to “server”">​</a></h5><p><a href="./Server.html"><code>Server</code></a></p><h5 id="connection" tabindex="-1">connection <a class="header-anchor" href="#connection" aria-label="Permalink to “connection”">​</a></h5><p><code>ClientConnection</code></p><h5 id="player" tabindex="-1">player <a class="header-anchor" href="#player" aria-label="Permalink to “player”">​</a></h5><p><a href="./Player.html"><code>Player</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>PlayerSession</code></p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="sender" tabindex="-1">sender <a class="header-anchor" href="#sender" aria-label="Permalink to “sender”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>sender</strong>(): <code>ChunkSender</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L243" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:243</a></p><p>The queue the scheduler drains - see ChunkRecipient.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><code>ChunkSender</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="addtoplayerlist" tabindex="-1">addToPlayerList() <a class="header-anchor" href="#addtoplayerlist" aria-label="Permalink to “addToPlayerList()”">​</a></h3><blockquote><p><strong>addToPlayerList</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1352" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1352</a></p><p>Adds the client to the player list of every player inside the server and also to the player itself.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="beginloadingscreen" tabindex="-1">beginLoadingScreen() <a class="header-anchor" href="#beginloadingscreen" aria-label="Permalink to “beginLoadingScreen()”">​</a></h3><blockquote><p><strong>beginLoadingScreen</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1156" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1156</a></p><p>Hands out the <code>Loading Screen Id</code> for a <code>ChangeDimensionPacket</code> about to be sent, and remembers it until <a href="#endloadingscreen">PlayerSession.endLoadingScreen</a> hears the client close that screen.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>A uint32 no other open screen on this session uses.</p><hr><h3 id="clearchunks" tabindex="-1">clearChunks() <a class="header-anchor" href="#clearchunks" aria-label="Permalink to “clearChunks()”">​</a></h3><blockquote><p><strong>clearChunks</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L661" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:661</a></p><p>Clear the currently loaded and loading chunks.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="remarks" tabindex="-1">Remarks <a class="header-anchor" href="#remarks" aria-label="Permalink to “Remarks”">​</a></h4><p>Usually used for changing dimension, world, etc.</p><p>Everything in flight goes with them. The two sets are only the bookkeeping; the queue of coordinates still to send and the chunks already produced but not yet dispatched are the actual work, and they belong to the world being left. Left in place, a dimension change sent the old world&#39;s terrain into the new one, and resolved the leftover coordinates against a world where they mean somewhere else entirely.</p><hr><h3 id="closewindow" tabindex="-1">closeWindow() <a class="header-anchor" href="#closewindow" aria-label="Permalink to “closeWindow()”">​</a></h3><blockquote><p><strong>closeWindow</strong>(<code>windowId</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L761" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:761</a></p><p>Forgets a window the client reports closed.</p><p>The docs have the server delete its container manager when the client&#39;s <code>ContainerClose</code> arrives, before answering it. Only a window this session opened can be closed here; any other id is left alone and reported through the return value so the handler can log it.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="windowid" tabindex="-1">windowId <a class="header-anchor" href="#windowid" aria-label="Permalink to “windowId”">​</a></h5><p><code>number</code></p><p>the <code>Container Id</code> the client sent.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>whether a window with that id was open.</p><hr><h3 id="considerentity" tabindex="-1">considerEntity() <a class="header-anchor" href="#considerentity" aria-label="Permalink to “considerEntity()”">​</a></h3><blockquote><p><strong>considerEntity</strong>(<code>entity</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L366" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:366</a></p><p>Shows one entity to this client, if it is close enough and not already shown.</p><p>The single-entity path, for something that has just entered the world rather than a whole pass over everything in it.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity" tabindex="-1">entity <a class="header-anchor" href="#entity" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>The entity to consider.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="deliver" tabindex="-1">deliver() <a class="header-anchor" href="#deliver" aria-label="Permalink to “deliver()”">​</a></h3><blockquote><p><strong>deliver</strong>(<code>x</code>, <code>z</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L256" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:256</a></p><p>Produces one chunk and queues it for the next batch. Called only by the scheduler.</p><p>The scheduler takes a coordinate off the queue before calling this, so a failure here has to put the bookkeeping back: <code>loadingChunks</code> is what stops <code>needNewChunks</code> from asking for the same chunk twice, and leaving the hash in it after nothing was sent means that chunk is never requested again - a permanent hole in the player&#39;s world for as long as they stay in range of it.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="z" tabindex="-1">z <a class="header-anchor" href="#z" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="despawnalltrackedentities" tabindex="-1">despawnAllTrackedEntities() <a class="header-anchor" href="#despawnalltrackedentities" aria-label="Permalink to “despawnAllTrackedEntities()”">​</a></h3><blockquote><p><strong>despawnAllTrackedEntities</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L395" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:395</a></p><p>Hides every tracked entity from this client and forgets them all.</p><p>For a world change. A dimension change does not make the client drop what it holds, so the mobs of the world being left stayed on screen in the new one. Not routed through <a href="#reconciletrackedentities">PlayerSession.reconcileTrackedEntities</a>: that returns early while another pass runs, and a world change cannot be skipped.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="dropentity" tabindex="-1">dropEntity() <a class="header-anchor" href="#dropentity" aria-label="Permalink to “dropEntity()”">​</a></h3><blockquote><p><strong>dropEntity</strong>(<code>entity</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L382" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:382</a></p><p>Hides one entity from this client if it is showing, and forgets it either way.</p><p>Unconditional forgetting matters: a stale id left behind would make the tracker believe the client still has an entity it does not, and block it from ever being sent again.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-1" tabindex="-1">entity <a class="header-anchor" href="#entity-1" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>The entity that is going away.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="endloadingscreen" tabindex="-1">endLoadingScreen() <a class="header-anchor" href="#endloadingscreen" aria-label="Permalink to “endLoadingScreen()”">​</a></h3><blockquote><p><strong>endLoadingScreen</strong>(<code>id</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1168" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1168</a></p><p>Records that the client closed a loading screen.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id" tabindex="-1">id <a class="header-anchor" href="#id" aria-label="Permalink to “id”">​</a></h5><p><code>number</code></p><p>The <code>Loading Screen Id</code> from the client&#39;s <code>ServerboundLoadingScreenPacket</code>.</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>Whether the id belonged to a screen this session had opened and not yet closed.</p><hr><h3 id="flush" tabindex="-1">flush() <a class="header-anchor" href="#flush" aria-label="Permalink to “flush()”">​</a></h3><blockquote><p><strong>flush</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L407" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:407</a></p><p>Sends what has been produced but not yet dispatched.</p><p>Called by the scheduler at the end of its pass, so a partial batch does not sit until the next tick.</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="flushqueuedmoves" tabindex="-1">flushQueuedMoves() <a class="header-anchor" href="#flushqueuedmoves" aria-label="Permalink to “flushQueuedMoves()”">​</a></h3><blockquote><p><strong>flushQueuedMoves</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1595" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1595</a></p><p>Sends this tick&#39;s movement as one batch.</p><p>Called once per world tick, after every entity has had its update.</p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>Resolves once the batch has been framed.</p><hr><h3 id="getconnection" tabindex="-1">getConnection() <a class="header-anchor" href="#getconnection" aria-label="Permalink to “getConnection()”">​</a></h3><blockquote><p><strong>getConnection</strong>(): <code>ClientConnection</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1680" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1680</a></p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>ClientConnection</code></p><hr><h3 id="getplayer" tabindex="-1">getPlayer() <a class="header-anchor" href="#getplayer" aria-label="Permalink to “getPlayer()”">​</a></h3><blockquote><p><strong>getPlayer</strong>(): <a href="./Player.html"><code>Player</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1684" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1684</a></p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./Player.html"><code>Player</code></a></p><hr><h3 id="isconnected" tabindex="-1">isConnected() <a class="header-anchor" href="#isconnected" aria-label="Permalink to “isConnected()”">​</a></h3><blockquote><p><strong>isConnected</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L266" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:266</a></p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="neednewchunks" tabindex="-1">needNewChunks() <a class="header-anchor" href="#neednewchunks" aria-label="Permalink to “needNewChunks()”">​</a></h3><blockquote><p><strong>needNewChunks</strong>(<code>forceResend?</code>, <code>dist?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L563" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:563</a></p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="forceresend" tabindex="-1">forceResend? <a class="header-anchor" href="#forceresend" aria-label="Permalink to “forceResend?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><h5 id="dist" tabindex="-1">dist? <a class="header-anchor" href="#dist" aria-label="Permalink to “dist?”">​</a></h5><p><code>number</code></p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="openmaininventory" tabindex="-1">openMainInventory() <a class="header-anchor" href="#openmaininventory" aria-label="Permalink to “openMainInventory()”">​</a></h3><blockquote><p><strong>openMainInventory</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L740" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:740</a></p><p>Opens the player&#39;s own inventory, as the client asked.</p><p>Under its own window id rather than under zero. Zero is the inventory the client always has open; asking it to <em>open</em> that one is asking for something it is already doing, and it answered by closing the window again straight away - which is as far as opening an inventory ever got, so no drag inside it was ever attempted.</p><p>The contents follow the open, because a window whose contents never arrive is one the client has no reason to keep.</p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="see" tabindex="-1">See <a class="header-anchor" href="#see" aria-label="Permalink to “See”">​</a></h4><p><a href="https://github.com/pmmp/PocketMine-MP/blob/stable/src/network/mcpe/InventoryManager.php" target="_blank" rel="noreferrer">https://github.com/pmmp/PocketMine-MP/blob/stable/src/network/mcpe/InventoryManager.php</a> (onClientOpenMainInventory)</p><hr><h3 id="queuechunks" tabindex="-1">queueChunks() <a class="header-anchor" href="#queuechunks" aria-label="Permalink to “queueChunks()”">​</a></h3><blockquote><p><strong>queueChunks</strong>(<code>centerX</code>, <code>centerZ</code>, <code>coordinates</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L271" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:271</a></p><p>Queues the chunks around a position, nearest first, without sending anything yet.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="centerx" tabindex="-1">centerX <a class="header-anchor" href="#centerx" aria-label="Permalink to “centerX”">​</a></h5><p><code>number</code></p><h5 id="centerz" tabindex="-1">centerZ <a class="header-anchor" href="#centerz" aria-label="Permalink to “centerZ”">​</a></h5><p><code>number</code></p><h5 id="coordinates" tabindex="-1">coordinates <a class="header-anchor" href="#coordinates" aria-label="Permalink to “coordinates”">​</a></h5><p>[<code>number</code>, <code>number</code>][]</p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="queuemoveactor" tabindex="-1">queueMoveActor() <a class="header-anchor" href="#queuemoveactor" aria-label="Permalink to “queueMoveActor()”">​</a></h3><blockquote><p><strong>queueMoveActor</strong>(<code>entity</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1581" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1581</a></p><p>Adds an entity&#39;s movement to this tick&#39;s batch.</p><p>Sending each one on its own is what made mobs move in fits and starts, and for two reasons. Every packet became its own compressed batch and its own RakNet frame, so thirty mobs cost thirty compressions and thirty frames a tick, per player. Worse, <code>sendDataPacket</code> queues behind any chunk still compressing - so while a walking player streams terrain, every mob&#39;s movement waited behind it and then arrived in a burst. Mobs froze and jumped in exactly the rhythm the chunks were arriving in.</p><p>One batch a tick fixes both: one compression, one frame, and one place in the queue for the lot of them.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-2" tabindex="-1">entity <a class="header-anchor" href="#entity-2" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>The entity that moved.</p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="reconciletrackedentities" tabindex="-1">reconcileTrackedEntities() <a class="header-anchor" href="#reconciletrackedentities" aria-label="Permalink to “reconcileTrackedEntities()”">​</a></h3><blockquote><p><strong>reconcileTrackedEntities</strong>(<code>entities?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L333" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:333</a></p><p>Shows and hides entities so the client matches where the player now is.</p><p>Records an entity as tracked only <em>after</em> its spawn has gone out. Marking first would mean a spawn that failed left the entity flagged as delivered, and nothing would ever send it again - the same lesson <code>flushChunkBatch</code> records for chunks, where it left a permanent hole in the world.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entities" tabindex="-1">entities? <a class="header-anchor" href="#entities" aria-label="Permalink to “entities?”">​</a></h5><p><code>Iterable</code>&lt;<a href="./Entity.html"><code>Entity</code></a>, <code>any</code>, <code>any</code>&gt;</p><p>Every entity in the world, and it must be every one - anything tracked and absent from it is taken to have left and is despawned. Defaults to asking the world. For a single arrival, use <a href="#considerentity">PlayerSession.considerEntity</a>.</p><h4 id="returns-20" tabindex="-1">Returns <a class="header-anchor" href="#returns-20" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="recordinputtick" tabindex="-1">recordInputTick() <a class="header-anchor" href="#recordinputtick" aria-label="Permalink to “recordInputTick()”">​</a></h3><blockquote><p><strong>recordInputTick</strong>(<code>tick</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1146" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1146</a></p><p>Remember the tick of a <code>PlayerAuthInputPacket</code> just handled, so packets about this player can carry it as their <code>PlayerInputTick</code>.</p><p>Ticks only move forward; an input that arrives out of order does not wind the value back.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tick" tabindex="-1">tick <a class="header-anchor" href="#tick" aria-label="Permalink to “tick”">​</a></h5><p><code>bigint</code></p><p>The packet&#39;s <code>Tick</code> field.</p><h4 id="returns-21" tabindex="-1">Returns <a class="header-anchor" href="#returns-21" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="removefromplayerlist" tabindex="-1">removeFromPlayerList() <a class="header-anchor" href="#removefromplayerlist" aria-label="Permalink to “removeFromPlayerList()”">​</a></h3><blockquote><p><strong>removeFromPlayerList</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1376" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1376</a></p><p>Removes a player from other players list</p><h4 id="returns-22" tabindex="-1">Returns <a class="header-anchor" href="#returns-22" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="requestchunk" tabindex="-1">requestChunk() <a class="header-anchor" href="#requestchunk" aria-label="Permalink to “requestChunk()”">​</a></h3><blockquote><p><strong>requestChunk</strong>(<code>x</code>, <code>z</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L644" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:644</a></p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-1" tabindex="-1">x <a class="header-anchor" href="#x-1" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="z-1" tabindex="-1">z <a class="header-anchor" href="#z-1" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-23" tabindex="-1">Returns <a class="header-anchor" href="#returns-23" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="send" tabindex="-1">send() <a class="header-anchor" href="#send" aria-label="Permalink to “send()”">​</a></h3><blockquote><p><strong>send</strong>(<code>packet</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L485" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:485</a></p><p>Sends one packet to this client.</p><p>Returns the send rather than dropping it: without this, every <code>await session.send(...)</code> and every <code>Promise.all</code> over a broadcast resolved immediately and any framing error went nowhere.</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="packet" tabindex="-1">packet <a class="header-anchor" href="#packet" aria-label="Permalink to “packet”">​</a></h5><p><a href="./../namespaces/Protocol/namespaces/Packets/classes/DataPacket.html"><code>DataPacket</code></a></p><p>The packet to send.</p><h4 id="returns-24" tabindex="-1">Returns <a class="header-anchor" href="#returns-24" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendabilities" tabindex="-1">sendAbilities() <a class="header-anchor" href="#sendabilities" aria-label="Permalink to “sendAbilities()”">​</a></h3><blockquote><p><strong>sendAbilities</strong>(<code>player?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L515" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:515</a></p><p>Sends <code>UpdateAbilitiesPacket</code> describing <code>player</code> to this client.</p><p>One <code>BASE</code> layer carries every ability, derived from the game mode and op state, with walk speed 0.1, fly speed 0.05 and vertical fly speed 1, the client&#39;s own defaults. The target id is the player&#39;s runtime id, which the server also uses as its unique id.</p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="player-1" tabindex="-1">player? <a class="header-anchor" href="#player-1" aria-label="Permalink to “player?”">​</a></h5><p><a href="./Player.html"><code>Player</code></a></p><p>The player described. Defaults to this session&#39;s own player.</p><h4 id="returns-25" tabindex="-1">Returns <a class="header-anchor" href="#returns-25" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendaddactor" tabindex="-1">sendAddActor() <a class="header-anchor" href="#sendaddactor" aria-label="Permalink to “sendAddActor()”">​</a></h3><blockquote><p><strong>sendAddActor</strong>(<code>entity</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1407" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1407</a></p><p>Writes an entity onto this connection.</p><p>Packet construction lives here rather than on the entity: what goes on the wire is the session&#39;s business, and an entity that built its own packets also had to reach into the world for the list of players to send them to.</p><h4 id="parameters-14" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-14" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-3" tabindex="-1">entity <a class="header-anchor" href="#entity-3" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>The entity to show.</p><h4 id="returns-26" tabindex="-1">Returns <a class="header-anchor" href="#returns-26" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendadditemactor" tabindex="-1">sendAddItemActor() <a class="header-anchor" href="#sendadditemactor" aria-label="Permalink to “sendAddItemActor()”">​</a></h3><blockquote><p><strong>sendAddItemActor</strong>(<code>item</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1492" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1492</a></p><p>Writes a dropped item onto this connection.</p><h4 id="parameters-15" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-15" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="item" tabindex="-1">item <a class="header-anchor" href="#item" aria-label="Permalink to “item”">​</a></h5><p><a href="./../namespaces/Entities/classes/Item.html"><code>Item</code></a></p><p>The item entity to show.</p><h4 id="returns-27" tabindex="-1">Returns <a class="header-anchor" href="#returns-27" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendarmorfor" tabindex="-1">sendArmorFor() <a class="header-anchor" href="#sendarmorfor" aria-label="Permalink to “sendArmorFor()”">​</a></h3><blockquote><p><strong>sendArmorFor</strong>(<code>wearer</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1445" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1445</a></p><p>Tells this client what a human is wearing and holding in the off hand.</p><p>All four armor pieces at once, empty ones included as air: the packet is positional and a client that was sent three would read the next packet&#39;s bytes as the fourth. <code>Body</code> is the body armor slot, which <code>HumanInventory</code> does not model, so it is always air. It used to carry the off-hand item, which the client took for body armor.</p><p>The off hand goes out as a <code>MobEquipmentPacket</code> for the offhand container, the way the client reports its own off-hand changes.</p><h4 id="parameters-16" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-16" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="wearer" tabindex="-1">wearer <a class="header-anchor" href="#wearer" aria-label="Permalink to “wearer”">​</a></h5><p><a href="./../namespaces/Entities/classes/Player.html"><code>Player</code></a></p><p>Whose armor it is.</p><h4 id="returns-28" tabindex="-1">Returns <a class="header-anchor" href="#returns-28" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendattributes" tabindex="-1">sendAttributes() <a class="header-anchor" href="#sendattributes" aria-label="Permalink to “sendAttributes()”">​</a></h3><blockquote><p><strong>sendAttributes</strong>(<code>attributes?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1093" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1093</a></p><p>Send the player&#39;s whole attribute set.</p><p>The client rebuilds the local player during the spawn sequence, so this has to be sent again once the player is in the world - anything sent before that is thrown away, which is why the hunger bar sat empty however correct the values were here.</p><h4 id="parameters-17" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-17" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="attributes" tabindex="-1">attributes? <a class="header-anchor" href="#attributes" aria-label="Permalink to “attributes?”">​</a></h5><p><a href="./Attributes.html"><code>Attributes</code></a> = <code>...</code></p><p>The attributes to send.</p><h4 id="returns-29" tabindex="-1">Returns <a class="header-anchor" href="#returns-29" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendattributesfor" tabindex="-1">sendAttributesFor() <a class="header-anchor" href="#sendattributesfor" aria-label="Permalink to “sendAttributesFor()”">​</a></h3><blockquote><p><strong>sendAttributesFor</strong>(<code>entity</code>, <code>attributes</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1127" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1127</a></p><p>Tell this client about <em>another</em> entity&#39;s changed attributes.</p><p>The gap that made mob combat invisible. Everything above sends the local player&#39;s own attributes, with their runtime id baked in, so a mob losing health changed a number on the server that no client was ever told about - the health bar over a hurt zombie never moved, and it died in one apparent hit from full. Attributes only reached a client once, inside the <code>AddActorPacket</code> that spawned the entity.</p><h4 id="parameters-18" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-18" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-4" tabindex="-1">entity <a class="header-anchor" href="#entity-4" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>Whose attributes these are.</p><h5 id="attributes-1" tabindex="-1">attributes <a class="header-anchor" href="#attributes-1" aria-label="Permalink to “attributes”">​</a></h5><p><a href="./Attribute.html"><code>Attribute</code></a>[]</p><p>The ones that changed; nothing is sent for an empty list.</p><h4 id="returns-30" tabindex="-1">Returns <a class="header-anchor" href="#returns-30" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendavailablecommands" tabindex="-1">sendAvailableCommands() <a class="header-anchor" href="#sendavailablecommands" aria-label="Permalink to “sendAvailableCommands()”">​</a></h3><blockquote><p><strong>sendAvailableCommands</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L902" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:902</a></p><p>Tells the client which commands this player may run and what each one takes.</p><p>One <code>CommandData</code> per command, each branch of its tree an overload, with overloads that come out the same folded into one. Only commands the player&#39;s permissions allow are sent, so the list is built per recipient and sent again when those permissions change.</p><h4 id="returns-31" tabindex="-1">Returns <a class="header-anchor" href="#returns-31" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendcraftingdata" tabindex="-1">sendCraftingData() <a class="header-anchor" href="#sendcraftingdata" aria-label="Permalink to “sendCraftingData()”">​</a></h3><blockquote><p><strong>sendCraftingData</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L789" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:789</a></p><p>Tells the client which recipes exist.</p><p>Until it has these the client proposes nothing and never sends a <code>CRAFTING_RECIPE</code>, so everything below this - the matcher, the stations, the grid - is invisible without it.</p><p>How many go out is <code>crafting-recipe-limit</code> in the config: <code>0</code> sends nothing, <code>-1</code> sends everything, and it starts at one. See there for why.</p><h4 id="returns-32" tabindex="-1">Returns <a class="header-anchor" href="#returns-32" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendcraftingslot" tabindex="-1">sendCraftingSlot() <a class="header-anchor" href="#sendcraftingslot" aria-label="Permalink to “sendCraftingSlot()”">​</a></h3><blockquote><p><strong>sendCraftingSlot</strong>(<code>wireSlot</code>, <code>item</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L719" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:719</a></p><p>Tells the client what one slot of its crafting grid now holds.</p><p>The grid lives in the player&#39;s own UI window rather than in the inventory, and an <code>ItemStackResponse</code> can only answer about slots the request named. A craft names none of them - the client sends <code>CraftingRecipe</code>, <code>CraftingResultsDeprecated</code> and <code>Take</code>, and no slot of the grid among them - so this is the only way to say the ingredients have been spent. Without it the log stayed on screen and could be crafted from for ever, while the server had already taken it.</p><h4 id="parameters-19" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-19" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="wireslot" tabindex="-1">wireSlot <a class="header-anchor" href="#wireslot" aria-label="Permalink to “wireSlot”">​</a></h5><p><code>number</code></p><p>the slot in the client&#39;s numbering, 28 upwards.</p><h5 id="item-1" tabindex="-1">item <a class="header-anchor" href="#item-1" aria-label="Permalink to “item”">​</a></h5><p><a href="./Item.html"><code>Item</code></a> | <code>null</code></p><p>what is there now, or <code>null</code> to empty it.</p><h4 id="returns-33" tabindex="-1">Returns <a class="header-anchor" href="#returns-33" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendcreativecontents" tabindex="-1">sendCreativeContents() <a class="header-anchor" href="#sendcreativecontents" aria-label="Permalink to “sendCreativeContents()”">​</a></h3><blockquote><p><strong>sendCreativeContents</strong>(<code>empty?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L809" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:809</a></p><h4 id="parameters-20" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-20" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="empty" tabindex="-1">empty? <a class="header-anchor" href="#empty" aria-label="Permalink to “empty?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><h4 id="returns-34" tabindex="-1">Returns <a class="header-anchor" href="#returns-34" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="senddespawn" tabindex="-1">sendDespawn() <a class="header-anchor" href="#senddespawn" aria-label="Permalink to “sendDespawn()”">​</a></h3><blockquote><p><strong>sendDespawn</strong>(<code>player</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1667" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1667</a></p><p>Despawn the player entity from another player</p><h4 id="parameters-21" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-21" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="player-2" tabindex="-1">player <a class="header-anchor" href="#player-2" aria-label="Permalink to “player”">​</a></h5><p><a href="./Player.html"><code>Player</code></a></p><h4 id="returns-35" tabindex="-1">Returns <a class="header-anchor" href="#returns-35" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendgamemode" tabindex="-1">sendGamemode() <a class="header-anchor" href="#sendgamemode" aria-label="Permalink to “sendGamemode()”">​</a></h3><blockquote><p><strong>sendGamemode</strong>(<code>gamemode?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L853" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:853</a></p><p>Send gamemode to a client.</p><h4 id="parameters-22" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-22" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="gamemode" tabindex="-1">gamemode? <a class="header-anchor" href="#gamemode" aria-label="Permalink to “gamemode?”">​</a></h5><p><a href="./../../minecraft/enumerations/Gametype.html"><code>Gametype</code></a></p><p>the numeric gamemode ID.</p><h4 id="returns-36" tabindex="-1">Returns <a class="header-anchor" href="#returns-36" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendgamerules" tabindex="-1">sendGameRules() <a class="header-anchor" href="#sendgamerules" aria-label="Permalink to “sendGameRules()”">​</a></h3><blockquote><p><strong>sendGameRules</strong>(<code>rules</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L881" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:881</a></p><p>Tells this client that game rules changed.</p><h4 id="parameters-23" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-23" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="rules" tabindex="-1">rules <a class="header-anchor" href="#rules" aria-label="Permalink to “rules”">​</a></h5><p><code>GameRule</code>[]</p><p>The rules that changed, spelled as the client spells them.</p><h4 id="returns-37" tabindex="-1">Returns <a class="header-anchor" href="#returns-37" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendgametypefor" tabindex="-1">sendGameTypeFor() <a class="header-anchor" href="#sendgametypefor" aria-label="Permalink to “sendGameTypeFor()”">​</a></h3><blockquote><p><strong>sendGameTypeFor</strong>(<code>target</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L869" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:869</a></p><p>Tells this client which game type a player now has.</p><p><code>UpdatePlayerGameTypePacket</code> is what the docs have the server send to every client after it accepts a game type change, because each client caches the game type and permission flags of every player it knows about. The Tick is this client&#39;s last input tick when the player is its own, so the client can reconcile the movement it predicted while the packet was in flight, and zero for anyone else, as the docs allow.</p><h4 id="parameters-24" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-24" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="target" tabindex="-1">target <a class="header-anchor" href="#target" aria-label="Permalink to “target”">​</a></h5><p><a href="./Player.html"><code>Player</code></a></p><p>The player whose game type changed.</p><h4 id="returns-38" tabindex="-1">Returns <a class="header-anchor" href="#returns-38" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendhanditem" tabindex="-1">sendHandItem() <a class="header-anchor" href="#sendhanditem" aria-label="Permalink to “sendHandItem()”">​</a></h3><blockquote><p><strong>sendHandItem</strong>(<code>item</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L829" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:829</a></p><p>Sets the item in the player hand.</p><h4 id="parameters-25" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-25" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="item-2" tabindex="-1">item <a class="header-anchor" href="#item-2" aria-label="Permalink to “item”">​</a></h5><p><a href="./Item.html"><code>Item</code></a></p><p>The entity.</p><h4 id="returns-39" tabindex="-1">Returns <a class="header-anchor" href="#returns-39" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendhelditemfor" tabindex="-1">sendHeldItemFor() <a class="header-anchor" href="#sendhelditemfor" aria-label="Permalink to “sendHeldItemFor()”">​</a></h3><blockquote><p><strong>sendHeldItemFor</strong>(<code>entity</code>, <code>item</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1475" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1475</a></p><p>Tells this client what another entity is holding.</p><h4 id="parameters-26" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-26" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-5" tabindex="-1">entity <a class="header-anchor" href="#entity-5" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>Whose hand it is in.</p><h5 id="item-3" tabindex="-1">item <a class="header-anchor" href="#item-3" aria-label="Permalink to “item”">​</a></h5><p><a href="./Item.html"><code>Item</code></a></p><p>What they are holding.</p><h4 id="returns-40" tabindex="-1">Returns <a class="header-anchor" href="#returns-40" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendinventory" tabindex="-1">sendInventory() <a class="header-anchor" href="#sendinventory" aria-label="Permalink to “sendInventory()”">​</a></h3><blockquote><p><strong>sendInventory</strong>(<code>windowId?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L681" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:681</a></p><p>Tells the client what the player is carrying.</p><p>The send was commented out, so the client was never told: it had no model of the player&#39;s own slots, and the server authoritative inventory system will not move a stack into a container it does not know. Every drag was refused on the client&#39;s side, before an <code>ItemStackRequest</code> was ever sent.</p><h4 id="parameters-27" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-27" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="windowid-1" tabindex="-1">windowId? <a class="header-anchor" href="#windowid-1" aria-label="Permalink to “windowId?”">​</a></h5><p><code>number</code> = <code>WindowIds.INVENTORY</code></p><h4 id="returns-41" tabindex="-1">Returns <a class="header-anchor" href="#returns-41" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendmessage" tabindex="-1">sendMessage() <a class="header-anchor" href="#sendmessage" aria-label="Permalink to “sendMessage()”">​</a></h3><blockquote><p><strong>sendMessage</strong>(<code>options</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1274" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1274</a></p><p>Send a chat message to the client.</p><h4 id="parameters-28" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-28" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options <a class="header-anchor" href="#options" aria-label="Permalink to “options”">​</a></h5><p>The options for the message.</p><h6 id="message" tabindex="-1">message <a class="header-anchor" href="#message" aria-label="Permalink to “message”">​</a></h6><p><code>string</code></p><p>The message to send.</p><h6 id="needstranslation" tabindex="-1">needsTranslation? <a class="header-anchor" href="#needstranslation" aria-label="Permalink to “needsTranslation?”">​</a></h6><p><code>boolean</code> = <code>false</code></p><p>Whether the message needs translation.</p><h6 id="parameters-29" tabindex="-1">parameters? <a class="header-anchor" href="#parameters-29" aria-label="Permalink to “parameters?”">​</a></h6><p><code>string</code>[] = <code>[]</code></p><p>The parameters for the message.</p><h6 id="platformchatid" tabindex="-1">platformChatId? <a class="header-anchor" href="#platformchatid" aria-label="Permalink to “platformChatId?”">​</a></h6><p><code>string</code> = <code>&#39;&#39;</code></p><p>The platform chat ID.</p><h6 id="sourcename" tabindex="-1">sourceName? <a class="header-anchor" href="#sourcename" aria-label="Permalink to “sourceName?”">​</a></h6><p><code>string</code> = <code>&#39;&#39;</code></p><p>The source of the message.</p><h6 id="type" tabindex="-1">type? <a class="header-anchor" href="#type" aria-label="Permalink to “type?”">​</a></h6><p><a href="./../namespaces/Protocol/namespaces/Types/enumerations/TextPacketType.html"><code>TextPacketType</code></a> = <code>TextPacketType.Raw</code></p><p>The type of the message.</p><h6 id="xuid" tabindex="-1">xuid? <a class="header-anchor" href="#xuid" aria-label="Permalink to “xuid?”">​</a></h6><p><code>string</code> = <code>&#39;&#39;</code></p><p>The XUID of the player.</p><h4 id="returns-42" tabindex="-1">Returns <a class="header-anchor" href="#returns-42" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><p>A promise that resolves when the message is sent.</p><hr><h3 id="sendmetadata" tabindex="-1">sendMetadata() <a class="header-anchor" href="#sendmetadata" aria-label="Permalink to “sendMetadata()”">​</a></h3><blockquote><p><strong>sendMetadata</strong>(<code>metadata?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1192" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1192</a></p><h4 id="parameters-30" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-30" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="metadata" tabindex="-1">metadata? <a class="header-anchor" href="#metadata" aria-label="Permalink to “metadata?”">​</a></h5><p><a href="./Metadata.html"><code>Metadata</code></a></p><h4 id="returns-43" tabindex="-1">Returns <a class="header-anchor" href="#returns-43" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendmetadatafor" tabindex="-1">sendMetadataFor() <a class="header-anchor" href="#sendmetadatafor" aria-label="Permalink to “sendMetadataFor()”">​</a></h3><blockquote><p><strong>sendMetadataFor</strong>(<code>entity</code>, <code>metadata?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1206" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1206</a></p><p>Tell this client what <em>another</em> entity now looks like.</p><p>The same gap <code>sendAttributesFor</code> fills, for the other half of an entity&#39;s state: everything above had the local player&#39;s runtime id baked in, so metadata reached a client exactly once, inside the packet that spawned the entity. A creeper could light its fuse, a mob could catch fire, and nobody would ever see either.</p><h4 id="parameters-31" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-31" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-6" tabindex="-1">entity <a class="header-anchor" href="#entity-6" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>Whose metadata this is.</p><h5 id="metadata-1" tabindex="-1">metadata? <a class="header-anchor" href="#metadata-1" aria-label="Permalink to “metadata?”">​</a></h5><p><a href="./Metadata.html"><code>Metadata</code></a></p><p>What to send; the entity&#39;s own by default.</p><h4 id="returns-44" tabindex="-1">Returns <a class="header-anchor" href="#returns-44" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendmotion" tabindex="-1">sendMotion() <a class="header-anchor" href="#sendmotion" aria-label="Permalink to “sendMotion()”">​</a></h3><blockquote><p><strong>sendMotion</strong>(<code>motion</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1184" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1184</a></p><p>Hand the client a velocity and let it move the player itself.</p><p>The only way to shove a player. Their position is theirs - the server stores what it is told - so setting it from here is overruled by the next movement packet and read as rubber-banding. A velocity is a request the client is happy to honor.</p><p>The <code>Tick</code> is the client&#39;s last input tick, as the docs ask for a packet about the player: the client rewinds to that tick, applies the velocity and replays what it predicted since. See <a href="#recordinputtick">PlayerSession.recordInputTick</a>.</p><h4 id="parameters-32" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-32" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="motion" tabindex="-1">motion <a class="header-anchor" href="#motion" aria-label="Permalink to “motion”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>Blocks per tick, in each axis.</p><h4 id="returns-45" tabindex="-1">Returns <a class="header-anchor" href="#returns-45" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendmove" tabindex="-1">sendMove() <a class="header-anchor" href="#sendmove" aria-label="Permalink to “sendMove()”">​</a></h3><blockquote><p><strong>sendMove</strong>(<code>player</code>, <code>mode?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1322" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1322</a></p><p>Sends one player&#39;s movement to this client.</p><p>Named for what it does. It was <code>broadcastMove</code>, which reads as a fan-out and is not one - the fan-out is <code>World.broadcastMove</code>, and having both made it easy to write the wrong one.</p><p>For this client&#39;s own player the packet is a server-initiated move: a teleport, a respawn, or a reset after a canceled move event. Its <code>Tick</code> is the client&#39;s last input tick, as the docs ask, so the client rewinds to it and replays its predictions from there. For any other player the packet is what this client sees of them, and the tick is zero because it relates to none of this client&#39;s inputs.</p><h4 id="parameters-33" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-33" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="player-3" tabindex="-1">player <a class="header-anchor" href="#player-3" aria-label="Permalink to “player”">​</a></h5><p><a href="./Player.html"><code>Player</code></a></p><p>The player that moved.</p><h5 id="mode" tabindex="-1">mode? <a class="header-anchor" href="#mode" aria-label="Permalink to “mode?”">​</a></h5><p><code>PositionMode</code> = <code>PositionMode.Normal</code></p><p>What produced the movement.</p><h4 id="returns-46" tabindex="-1">Returns <a class="header-anchor" href="#returns-46" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendmoveactor" tabindex="-1">sendMoveActor() <a class="header-anchor" href="#sendmoveactor" aria-label="Permalink to “sendMoveActor()”">​</a></h3><blockquote><p><strong>sendMoveActor</strong>(<code>entity</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1563" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1563</a></p><p>Tells this connection an entity has moved, on its own.</p><p>For a move that happens outside the world tick - a teleport, a command. Movement produced by the tick goes through <a href="#queuemoveactor">queueMoveActor</a> instead.</p><h4 id="parameters-34" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-34" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-7" tabindex="-1">entity <a class="header-anchor" href="#entity-7" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>The entity that moved.</p><h4 id="returns-47" tabindex="-1">Returns <a class="header-anchor" href="#returns-47" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendnetworkchunkpublisher" tabindex="-1">sendNetworkChunkPublisher() <a class="header-anchor" href="#sendnetworkchunkpublisher" aria-label="Permalink to “sendNetworkChunkPublisher()”">​</a></h3><blockquote><p><strong>sendNetworkChunkPublisher</strong>(<code>distance</code>, <code>savedChunks</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L887" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:887</a></p><h4 id="parameters-35" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-35" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="distance" tabindex="-1">distance <a class="header-anchor" href="#distance" aria-label="Permalink to “distance”">​</a></h5><p><code>number</code></p><h5 id="savedchunks" tabindex="-1">savedChunks <a class="header-anchor" href="#savedchunks" aria-label="Permalink to “savedChunks”">​</a></h5><p><code>ChunkCoord</code>[]</p><h4 id="returns-48" tabindex="-1">Returns <a class="header-anchor" href="#returns-48" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendplayerlist" tabindex="-1">sendPlayerList() <a class="header-anchor" href="#sendplayerlist" aria-label="Permalink to “sendPlayerList()”">​</a></h3><blockquote><p><strong>sendPlayerList</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1392" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1392</a></p><p>Sends the full player list to the player.</p><h4 id="returns-49" tabindex="-1">Returns <a class="header-anchor" href="#returns-49" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendplaystatus" tabindex="-1">sendPlayStatus() <a class="header-anchor" href="#sendplaystatus" aria-label="Permalink to “sendPlayStatus()”">​</a></h3><blockquote><p><strong>sendPlayStatus</strong>(<code>status</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1674" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1674</a></p><p>Sends a <code>PlayStatus</code> to this player&#39;s client.</p><h4 id="parameters-36" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-36" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to “status”">​</a></h5><p><code>PlayStatus</code></p><h4 id="returns-50" tabindex="-1">Returns <a class="header-anchor" href="#returns-50" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendremoveactor" tabindex="-1">sendRemoveActor() <a class="header-anchor" href="#sendremoveactor" aria-label="Permalink to “sendRemoveActor()”">​</a></h3><blockquote><p><strong>sendRemoveActor</strong>(<code>entity</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1510" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1510</a></p><p>Takes an entity off this connection.</p><h4 id="parameters-37" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-37" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-8" tabindex="-1">entity <a class="header-anchor" href="#entity-8" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>The entity to remove.</p><h4 id="returns-51" tabindex="-1">Returns <a class="header-anchor" href="#returns-51" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendremoveactorbyid" tabindex="-1">sendRemoveActorById() <a class="header-anchor" href="#sendremoveactorbyid" aria-label="Permalink to “sendRemoveActorById()”">​</a></h3><blockquote><p><strong>sendRemoveActorById</strong>(<code>runtimeId</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1523" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1523</a></p><p>Takes an entity off this client by id.</p><p>By id rather than by entity because the tracker has to be able to hide something that has already left the world - there is no object left to ask. Correct for every kind of entity: <code>RemoveActorPacket</code> is what both <code>Entity.despawnFrom</code> and <code>Player.despawnFrom</code> end up sending, players included.</p><h4 id="parameters-38" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-38" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="runtimeid" tabindex="-1">runtimeId <a class="header-anchor" href="#runtimeid" aria-label="Permalink to “runtimeId”">​</a></h5><p><code>bigint</code></p><p>The entity&#39;s runtime id.</p><h4 id="returns-52" tabindex="-1">Returns <a class="header-anchor" href="#returns-52" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendrespawn" tabindex="-1">sendRespawn() <a class="header-anchor" href="#sendrespawn" aria-label="Permalink to “sendRespawn()”">​</a></h3><blockquote><p><strong>sendRespawn</strong>(<code>position</code>, <code>state</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1254" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1254</a></p><p>One of the server&#39;s two halves of the respawn exchange.</p><p>The order matters and is not obvious. <code>SearchingForSpawn</code> goes out the moment the player dies, carrying where they will reappear; the client then shows its death screen. <code>ReadyToSpawn</code> is the <em>answer</em> to the client saying it has finished loading, and goes out only then.</p><p>Sending the second in place of the first leaves the client on &quot;Respawning&quot; for ever: it is waiting to be told where it will come back before it will even offer the button.</p><p><code>Player Runtime Id</code> is always 0, as in every <code>Respawn</code> a Bedrock Dedicated Server 1.26.52 sends, at the join and after a death.</p><h4 id="parameters-39" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-39" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position" tabindex="-1">position <a class="header-anchor" href="#position" aria-label="Permalink to “position”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>Where the player will reappear.</p><h5 id="state" tabindex="-1">state <a class="header-anchor" href="#state" aria-label="Permalink to “state”">​</a></h5><p><code>PlayerRespawnState</code></p><p>Which half of the exchange this is.</p><h4 id="returns-53" tabindex="-1">Returns <a class="header-anchor" href="#returns-53" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="see-1" tabindex="-1">See <a class="header-anchor" href="#see-1" aria-label="Permalink to “See”">​</a></h4><p><a href="https://github.com/pmmp/PocketMine-MP/blob/stable/src/network/mcpe/handler/DeathPacketHandler.php" target="_blank" rel="noreferrer">https://github.com/pmmp/PocketMine-MP/blob/stable/src/network/mcpe/handler/DeathPacketHandler.php</a></p><hr><h3 id="sendrespawned" tabindex="-1">sendRespawned() <a class="header-anchor" href="#sendrespawned" aria-label="Permalink to “sendRespawned()”">​</a></h3><blockquote><p><strong>sendRespawned</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1223" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1223</a></p><p>Tells the client its player is alive again, as a Bedrock Dedicated Server 1.26.52 does when the respawn button is pressed: <code>ActorEvent(SPAWN_ALIVE)</code> for the player, its health, then its attributes and actor data.</p><p>No <code>MovePlayer</code>: the client has put itself at the <code>ReadyToSpawn</code> position already.</p><h4 id="returns-54" tabindex="-1">Returns <a class="header-anchor" href="#returns-54" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendsettings" tabindex="-1">sendSettings() <a class="header-anchor" href="#sendsettings" aria-label="Permalink to “sendSettings()”">​</a></h3><blockquote><p><strong>sendSettings</strong>(<code>player?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L494" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:494</a></p><p>Notify a client about change(s) to the adventure settings.</p><h4 id="parameters-40" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-40" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="player-4" tabindex="-1">player? <a class="header-anchor" href="#player-4" aria-label="Permalink to “player?”">​</a></h5><p><a href="./Player.html"><code>Player</code></a></p><p>The client-controlled entity</p><h4 id="returns-55" tabindex="-1">Returns <a class="header-anchor" href="#returns-55" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendspawn" tabindex="-1">sendSpawn() <a class="header-anchor" href="#sendspawn" aria-label="Permalink to “sendSpawn()”">​</a></h3><blockquote><p><strong>sendSpawn</strong>(<code>player</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1612" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1612</a></p><p>Spawn the player for another player</p><h4 id="parameters-41" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-41" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="player-5" tabindex="-1">player <a class="header-anchor" href="#player-5" aria-label="Permalink to “player”">​</a></h5><p><a href="./Player.html"><code>Player</code></a></p><p>the player to send the AddPlayerPacket to</p><h4 id="returns-56" tabindex="-1">Returns <a class="header-anchor" href="#returns-56" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendtime" tabindex="-1">sendTime() <a class="header-anchor" href="#sendtime" aria-label="Permalink to “sendTime()”">​</a></h3><blockquote><p><strong>sendTime</strong>(<code>tick</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L843" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:843</a></p><p>Send the current tick to a client.</p><h4 id="parameters-42" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-42" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tick-1" tabindex="-1">tick <a class="header-anchor" href="#tick-1" aria-label="Permalink to “tick”">​</a></h5><p><code>number</code></p><p>The tick</p><h4 id="returns-57" tabindex="-1">Returns <a class="header-anchor" href="#returns-57" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="setviewdistance" tabindex="-1">setViewDistance() <a class="header-anchor" href="#setviewdistance" aria-label="Permalink to “setViewDistance()”">​</a></h3><blockquote><p><strong>setViewDistance</strong>(<code>distance</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1039" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1039</a></p><p>Set the client&#39;s maximum view distance.</p><h4 id="parameters-43" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-43" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="distance-1" tabindex="-1">distance <a class="header-anchor" href="#distance-1" aria-label="Permalink to “distance”">​</a></h5><p><code>number</code></p><p>The view distance</p><h4 id="returns-58" tabindex="-1">Returns <a class="header-anchor" href="#returns-58" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="syncattributes" tabindex="-1">syncAttributes() <a class="header-anchor" href="#syncattributes" aria-label="Permalink to “syncAttributes()”">​</a></h3><blockquote><p><strong>syncAttributes</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L1104" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:1104</a></p><p>Send only the attributes that changed since the last sync, if any.</p><p>Called every tick from <a href="./Player.html#update">Player.update</a>: a value nothing tells the client about is a value that only exists on the server.</p><h4 id="returns-59" tabindex="-1">Returns <a class="header-anchor" href="#returns-59" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="tracks" tabindex="-1">tracks() <a class="header-anchor" href="#tracks" aria-label="Permalink to “tracks()”">​</a></h3><blockquote><p><strong>tracks</strong>(<code>runtimeId</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L318" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:318</a></p><p>Whether this client knows about the entity.</p><p>True for the player&#39;s own entity, which the tracker itself never holds - a client is not sent a spawn for the thing it is driving, but it plainly <em>has</em> it. Without this the gates built on <code>tracks</code> would drop a player&#39;s own hurt animation and the pickup animation for the item they just walked over.</p><h4 id="parameters-44" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-44" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="runtimeid-1" tabindex="-1">runtimeId <a class="header-anchor" href="#runtimeid-1" aria-label="Permalink to “runtimeId”">​</a></h5><p><code>bigint</code></p><p>The entity&#39;s runtime id.</p><h4 id="returns-60" tabindex="-1">Returns <a class="header-anchor" href="#returns-60" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p><code>true</code> if the client can act on a packet naming that id.</p><hr><h3 id="update" tabindex="-1">update() <a class="header-anchor" href="#update" aria-label="Permalink to “update()”">​</a></h3><blockquote><p><strong>update</strong>(<code>_tick</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L292" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:292</a></p><p>Per-tick work for this client: terrain to request, entities to show or hide.</p><p>Both hang off the same question - has the player walked into a different chunk. Asking it here rather than inside each is what stops <code>needNewChunks</code> rebuilding a heap of a few hundred candidates twenty times a second for a player who has not moved, and it is what makes a moving player see entities appear within a tick rather than on the next interval.</p><h4 id="parameters-45" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-45" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tick-2" tabindex="-1">_tick <a class="header-anchor" href="#tick-2" aria-label="Permalink to “_tick”">​</a></h5><p><code>number</code></p><p>The current server tick.</p><h4 id="returns-61" tabindex="-1">Returns <a class="header-anchor" href="#returns-61" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to “Lifecycle”">​</a></h2><h3 id="disable" tabindex="-1">disable() <a class="header-anchor" href="#disable" aria-label="Permalink to “disable()”">​</a></h3><blockquote><p><strong>disable</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L238" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:238</a></p><p>Takes this client back out of the chunk rotation. Paired with <a href="#enable">PlayerSession.enable</a> and safe to call more than once.</p><h4 id="returns-62" tabindex="-1">Returns <a class="header-anchor" href="#returns-62" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="enable" tabindex="-1">enable() <a class="header-anchor" href="#enable" aria-label="Permalink to “enable()”">​</a></h3><blockquote><p><strong>enable</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/37a83bc764e747de8afd768e39615e04af067e9d/packages/prismarine/src/network/PlayerSession.ts#L229" target="_blank" rel="noreferrer">packages/prismarine/src/network/PlayerSession.ts:229</a></p><p>Puts this client into the server-wide rotation that feeds it chunks.</p><p>Not done in the constructor: a session that is built and then thrown away - a join that fails part way through - would stay in the scheduler&#39;s set for the life of the server, because the scheduler only ever skips the disconnected and removes on request.</p><h4 id="returns-63" tabindex="-1">Returns <a class="header-anchor" href="#returns-63" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p>`,720)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};